from pathlib import Path
import hashlib
import html
import json

root = Path(__file__).resolve().parent.parent
media = root / 'DO_WGRANIA'
preview = root / 'podglad'
preview.mkdir(exist_ok=True)

films = [
    ('Cel kalorii dla redukcji', 'Diecik-automatyczny-cel-kalorii-Reels-Stories-20s.mp4', 'deficit'),
    ('Generator diety', 'Diecik-generator-diety-Reels-Stories-20s.mp4', 'generator'),
]

def versioned(p):
    return html.escape(p.name + '?v=' + hashlib.sha256(p.read_bytes()).hexdigest()[:12], quote=True)

buttons = ''.join(f'<button class="choice" data-src="../DO_WGRANIA/{versioned(media / name)}" data-poster="okladki/{slug}.jpg">{html.escape(title)}<span>20 s · 9:16 · z muzyką</span></button>' for title, name, slug in films)
statics = ''.join(f'<a class="asset" href="../DO_WGRANIA/{versioned(p)}" target="_blank"><img loading="lazy" src="../DO_WGRANIA/{versioned(p)}" alt="{html.escape(p.stem)}"><span>{"Cel kalorii" if "Cel-kalorii" in p.name else "Generator diety"} · {"1:1" if "1x1" in p.name else "4:5"}</span></a>' for p in sorted(media.glob('Grafika-*.jpg')))
carousel = ''.join(f'<a class="asset" href="../DO_WGRANIA/{versioned(p)}" target="_blank"><img loading="lazy" src="../DO_WGRANIA/{versioned(p)}" alt="{html.escape(p.stem)}"><span>{i}. {label}</span></a>' for i, (p, label) in enumerate(zip(sorted(media.glob('Karuzela-*.jpg')), ['Cel kalorii', 'Ustawienia generatora', 'Podgląd posiłków', 'Zapis planu']), 1))

